#!/usr/bin/env bash
# Clean Code Agent — protected-file guard (PreToolUse hook for Edit/Write).
# Asks the user before an edit to files a cleanup should never touch on its own:
# lockfiles, vendored/third-party code, generated files, migrations, snapshots, .env files.
# Pure bash, no dependencies. Unknown input -> no decision (normal permissions apply).

input=$(cat)
file=$(printf '%s' "$input" | sed -n 's/.*"file_path"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n1)
[[ -z "$file" ]] && exit 0

reason=""
base=${file##*/}
case "$base" in
  package-lock.json|npm-shrinkwrap.json|yarn.lock|pnpm-lock.yaml|bun.lockb|bun.lock|poetry.lock|Pipfile.lock|uv.lock|Cargo.lock|composer.lock|Gemfile.lock|go.sum|packages.lock.json|mix.lock|pubspec.lock)
    reason="lockfile" ;;
  .env|.env.*) reason="environment/secrets file" ;;
  *.min.js|*.min.css|*.map) reason="minified or compiled output" ;;
  *.snap) reason="test snapshot" ;;
esac
if [[ -z "$reason" ]]; then
  case "/$file" in
    */node_modules/*|*/vendor/*|*/third_party/*|*/third-party/*|*/external/*) reason="vendored or third-party code" ;;
    */migrations/*|*/migrate/*|*/db/migrate/*|*/alembic/versions/*) reason="database migration" ;;
    */__snapshots__/*) reason="test snapshot" ;;
    */dist/*|*/build/*) reason="build output" ;;
  esac
fi
if [[ -z "$reason" && -f "$file" ]] && head -n 15 "$file" 2>/dev/null | grep -qiE 'do not edit|@generated|code generated|auto-?generated|generated by'; then
  reason="generated file (has a 'generated / do not edit' header)"
fi

[[ -z "$reason" ]] && exit 0

msg="Clean Code guard: ${file} looks like a ${reason}. A cleanup should not change it without your explicit OK."
msg=${msg//\\/\\\\}; msg=${msg//\"/\\\"}
printf '{"hookSpecificOutput":{"hookEventName":"PreToolUse","permissionDecision":"ask","permissionDecisionReason":"%s"}}\n' "$msg"
